import React from 'react';
import {AbsoluteFill, interpolate, Easing} from 'remotion';
import {useS, en, clamp, DUR} from './kit';

const W = 1080;
const H = 1920;

// Momentos atados a la voz (palabras exactas del guion)
const CLAMAS = en('clamas');
const SILENCIAN = en('silencian');
const HISTORIA = en('historia');
const BARTIMEO = en('Bartimeo');
const CIEGO = en('ciego');
const OYE = en('oye');
const JESUS1 = en('Jesús');
const PASAR = en('pasar');
const GRITA1 = en('Grita');
const HIJO = en('Hijo');
const DAVID = en('David');
const MISERICORDIA = en('misericordia');
const MULTITUD = en('multitud');
const REGAA = en('regaña');
const GRITA2 = en('grita');
const DETIENE1 = en('detiene');
const MANDA = en('manda');
const LLAMARLE = en('llamarle');
const ANIMO = en('Ánimo');
const LEVANTATE = en('levántate');
const LLAMA = en('llama');
const TIRA = en('tira');
const MANTO = en('manto');
const VA = en('va');
const PREGUNTA1 = en('pregunta');
const QUIERES1 = en('quieres');
const SENOR = en('Señor');
const VEA = en('vea');
const FE1 = en('fe');
const SALVO = en('salvó');
const INSTANTE = en('instante');
const VE = en('ve');
const SIGUE = en('sigue');
const INVISIBLE = en('invisible');
const GRITO = en('grito');
const IMPORTA = en('importa');
const PASA = en('pasa');
const LARGO = en('largo');
const CLAMAS2 = en('clamas');
const FE2 = en('fe');
const DETIENE2 = en('detiene');
const PREGUNTA2 = en('pregunta');
const QUIERES2 = en('quieres');
const CONFIA = en('Confía');
const GRITA3 = en('grita');
const FE3 = en('fe');
const SALVA = en('salva');
const AMEN = en('Amén');

// Utilidades
const mix = (a: number[], b: number[], k: number) => a.map((x, i) => x + (b[i] - x) * k);
const rgb = (c: number[]) => `rgb(${c.map(Math.round).join(',')})`;

// Cielo que transiciona de día a luz dorada
const Cielo: React.FC<{progreso: number}> = ({progreso}) => {
  const dia = [180, 200, 230];
  const oro = [255, 210, 140];
  const noche = [25, 30, 55];
  const c = progreso < 0.5 ? mix(dia, oro, progreso * 2) : mix(oro, noche, (progreso - 0.5) * 2);
  return <AbsoluteFill style={{background: `linear-gradient(180deg, ${rgb(c)} 0%, ${rgb(mix(c, [255,255,255], 0.3))} 100%)`}} />;
};

// Sol/luz divina que crece
const LuzDivina: React.FC<{intensidad: number; s: number}> = ({intensidad, s}) => {
  const y = interpolate(intensidad, [0, 1], [1600, 400], clamp);
  const r = 120 + intensidad * 200 + Math.sin(s * 0.8) * 15;
  return (
    <div style={{position: 'absolute', left: W/2 - r, top: y - r, width: r*2, height: r*2, opacity: intensidad, pointerEvents: 'none'}}>
      <div style={{position: 'absolute', inset: 0, borderRadius: '50%', background: `radial-gradient(circle, rgba(255,240,180,${0.6*intensidad}) 0%, rgba(255,200,100,${0.2*intensidad}) 40%, transparent 70%)`}} />
      <div style={{position: 'absolute', left: r*0.3, top: r*0.3, width: r*1.4, height: r*1.4, borderRadius: '50%', background: `radial-gradient(circle at 40% 30%, #fffef0 0%, #ffe8b0 50%, #ffcc60 100%)`, boxShadow: `0 0 ${80*intensidad}px ${30*intensidad}px rgba(255,220,140,${0.5*intensidad})`}} />
    </div>
  );
};

// Rayos de luz que bajan
const Rayos: React.FC<{fuerza: number; s: number}> = ({fuerza, s}) => (
  <AbsoluteFill style={{opacity: fuerza * 0.4, mixBlendMode: 'screen', pointerEvents: 'none'}}>
    {Array.from({length: 11}).map((_, i) => {
      const ang = -50 + i * 10 + Math.sin(s * 0.25 + i) * 1.5;
      return <div key={i} style={{position: 'absolute', left: W/2 - 30, top: 400, width: 60, height: 1800, transformOrigin: '50% 0%', transform: `rotate(${ang + 180}deg)`, background: 'linear-gradient(180deg, rgba(255,235,180,0.6), transparent 85%)', filter: 'blur(18px)'}} />;
    })}
  </AbsoluteFill>
);

// Polvo/partículas en el aire
const Polvo: React.FC<{s: number; calido: number}> = ({s, calido}) => (
  <AbsoluteFill style={{pointerEvents: 'none'}}>
    {Array.from({length: 50}).map((_, i) => {
      const x = (i * 197) % W + Math.sin(s * 0.3 + i) * 40;
      const y = H - ((i * 311 + s * (12 + (i%5)*6)) % (H + 200));
      const r = 1.5 + (i % 3);
      return <div key={i} style={{position: 'absolute', left: x, top: y, width: r, height: r, borderRadius: r, background: calido > 0.5 ? '#ffe8b0' : '#c8d0e8', opacity: 0.2 + 0.3 * Math.sin(s + i)}} />;
    })}
  </AbsoluteFill>
);

// Camino de Jericó con perspectiva
const Camino: React.FC<{progreso: number; s: number}> = ({progreso, s}) => {
  const deriva = Math.sin(s * 0.12) * 15;
  return (
    <svg width={W} height={H} style={{position: 'absolute', left: 0, top: 0, pointerEvents: 'none'}} viewBox={`0 0 ${W} ${H}`}>
      <defs>
        <linearGradient id="caminoGrad" x1="0" y1="1" x2="0" y2="0">
          <stop offset="0%" stopColor="#8b7a5a" />
          <stop offset="100%" stopColor="#d4c4a0" />
        </linearGradient>
        <linearGradient id="pastoGrad" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stopColor="#3a5a2a" />
          <stop offset="100%" stopColor="#2a3a1a" />
        </linearGradient>
      </defs>
      {/* Pasto lados */}
      <path d={`M 0 ${H} L ${W*0.35 + deriva*0.5} ${H*0.55} L ${W*0.45 + deriva*0.5} ${H*0.55} L 0 ${H} Z`} fill="url(#pastoGrad)" opacity={0.9} />
      <path d={`M ${W} ${H} L ${W*0.65 + deriva*0.5} ${H*0.55} L ${W*0.55 + deriva*0.5} ${H*0.55} L ${W} ${H} Z`} fill="url(#pastoGrad)" opacity={0.9} />
      {/* Camino */}
      <path d={`M ${W*0.35 + deriva*0.5} ${H*0.55} L ${W*0.45 + deriva*0.5} ${H*0.55} L ${W*0.55 + deriva*0.5} ${H*0.55} L ${W*0.65 + deriva*0.5} ${H*0.55} L ${W*0.8} ${H} L ${W*0.2} ${H} Z`} fill="url(#caminoGrad)" opacity={0.95} />
      {/* Piedras del camino */}
      {Array.from({length: 20}).map((_, i) => {
        const px = W*0.38 + (i%4)*40 + Math.sin(s*0.5+i)*3;
        const py = H*0.58 + Math.floor(i/4)*80 + Math.cos(s*0.4+i)*5;
        return <circle key={i} cx={px} cy={py} r={4 + (i%3)*2} fill="#6b5b3a" opacity={0.6} />;
      })}
    </svg>
  );
};

// Figura de Bartimeo (muñequito sereno, sentado luego de pie)
const Bartimeo: React.FC<{s: number; fase: number; x: number; y: number; escala: number}> = ({s, fase, x, y, escala}) => {
  const respira = Math.sin(s * 1.3) * 2 * escala;
  const estaSentado = fase < 1.5;
  const brazosAbiertos = fase > 2.5;
  const manosJuntas = fase > 3.5;
  return (
    <div style={{position: 'absolute', left: x - 60*escala, top: y - (estaSentado ? 100 : 160)*escala, transform: `scale(${escala}) translateY(${respira}px)`, pointerEvents: 'none'}}>
      {/* Sombra */}
      <ellipse cx={60*escala} cy={180*escala} rx={40*escala} ry={10*escala} fill="rgba(0,0,0,0.25)" />
      {/* Cuerpo */}
      <svg width={120*escala} height={200*escala} viewBox="0 0 120 200" style={{position: 'absolute', left: 0, top: 0}}>
        {/* Túnica */}
        <path d={`M 20 180 L 25 ${estaSentado ? 80 : 40} Q 60 ${estaSentado ? 60 : 20} 95 ${estaSentado ? 80 : 40} L 100 180 Z`} fill="#5a4a3a" />
        <path d={`M 30 180 L 35 ${estaSentado ? 90 : 50} Q 60 ${estaSentado ? 70 : 30} 85 ${estaSentado ? 90 : 50} L 90 180 Z`} fill="#6b5a45" />
        {/* Cinturón */}
        <rect x={45} y={estaSentado ? 110 : 80} width={30} height={6} fill="#3a2f22" />
        {/* Cabeza */}
        <circle cx={60} cy={estaSentado ? 55 : 25} r={22} fill="#e8c8a0" />
        {/* Ojos cerrados (ciego) - serenos */}
        <ellipse cx={50} cy={estaSentado ? 52 : 22} rx={6} ry={2} fill="#2a1a10" />
        <ellipse cx={70} cy={estaSentado ? 52 : 22} rx={6} ry={2} fill="#2a1a10" />
        {/* Cejas serenas */}
        <path d="M 44 45 Q 50 43 56 45" stroke="#4a3a2a" strokeWidth="1.5" fill="none" />
        <path d="M 64 45 Q 70 43 76 45" stroke="#4a3a2a" strokeWidth="1.5" fill="none" />
        {/* Boca serena */}
        <path d="M 50 62 Q 60 66 70 62" stroke="#4a3a2a" strokeWidth="1.5" fill="none" />
        {/* Barba ligera */}
        <path d="M 45 70 Q 60 78 75 70" stroke="#b89878" strokeWidth="1" fill="none" opacity={0.6} />
        {/* Brazos */}
        {brazosAbiertos && (
          <>
            <path d="M 30 90 Q 10 110 5 140" stroke="#5a4a3a" strokeWidth={14} strokeLinecap="round" fill="none" />
            <path d="M 90 90 Q 110 110 115 140" stroke="#5a4a3a" strokeWidth={14} strokeLinecap="round" fill="none" />
            <circle cx={15} cy={145} r={8} fill="#e8c8a0" />
            <circle cx={105} cy={145} r={8} fill="#e8c8a0" />
          </>
        )}
        {manosJuntas && (
          <>
            <path d="M 45 90 Q 55 85 60 95 Q 65 85 75 90" stroke="#5a4a3a" strokeWidth={12} strokeLinecap="round" fill="none" />
            <circle cx={60} cy={95} r={10} fill="#e8c8a0" />
          </>
        )}
        {!brazosAbiertos && !manosJuntas && (
          <>
            <path d="M 30 90 Q 25 120 30 150" stroke="#5a4a3a" strokeWidth={12} strokeLinecap="round" fill="none" />
            <path d="M 90 90 Q 95 120 90 150" stroke="#5a4a3a" strokeWidth={12} strokeLinecap="round" fill="none" />
            <circle cx={30} cy={150} r={7} fill="#e8c8a0" />
            <circle cx={90} cy={150} r={7} fill="#e8c8a0" />
          </>
        )}
        {/* Manto en el suelo (fase 2) */}
        {fase > 1.5 && fase < 3 && (
          <ellipse cx={60} cy={185} rx={45} ry={8} fill="#3a3025" opacity={interpolate(fase, [1.5, 2], [1, 0], clamp)} />
        )}
      </svg>
    </div>
  );
};

// Figura de Jesús (solo silueta/espalda, nunca rostro)
const Jesus: React.FC<{s: number; presente: number; x: number; y: number; escala: number}> = ({s, presente, x, y, escala}) => {
  if (presente <= 0) return null;
  const respira = Math.sin(s * 1.1) * 1.5 * escala;
  return (
    <div style={{position: 'absolute', left: x - 50*escala, top: y - 170*escala, transform: `scale(${escala}) translateY(${respira}px)`, opacity: presente, pointerEvents: 'none'}}>
      <svg width={100*escala} height={200*escala} viewBox="0 0 100 200">
        {/* Aureola suave */}
        <circle cx={50} cy={30} r={35} fill="rgba(255,230,150,0.3)" filter="blur(8px)" />
        {/* Túnica larga */}
        <path d="M 15 190 L 20 30 Q 50 10 80 30 L 85 190 Z" fill="#f5f0e0" />
        <path d="M 25 190 L 30 40 Q 50 20 70 40 L 75 190 Z" fill="#ede6d0" />
        {/* Manto sobre hombros */}
        <path d="M 15 50 Q 30 35 50 30 Q 70 35 85 50 L 85 80 Q 50 60 15 80 Z" fill="rgba(100,80,50,0.4)" />
        {/* Cabello */}
        <path d="M 30 45 Q 35 25 50 20 Q 65 25 70 45" fill="#4a3a2a" />
        {/* Manos extendidas en bendición */}
        <path d="M 30 80 Q 20 100 15 130" stroke="#e8c8a0" strokeWidth={10} strokeLinecap="round" fill="none" />
        <path d="M 70 80 Q 80 100 85 130" stroke="#e8c8a0" strokeWidth={10} strokeLinecap="round" fill="none" />
        <circle cx={15} cy={130} r={7} fill="#e8c8a0" />
        <circle cx={85} cy={130} r={7} fill="#e8c8a0" />
      </svg>
    </div>
  );
};

// Multitud (siluetas que se mueven, luego se apartan)
const Multitud: React.FC<{s: number; fase: number}> = ({s, fase}) => {
  const intensidad = fase < 1 ? 1 : interpolate(fase, [1, 2], [1, 0], clamp);
  if (intensidad <= 0) return null;
  return (
    <AbsoluteFill style={{pointerEvents: 'none', opacity: intensidad}}>
      {Array.from({length: 12}).map((_, i) => {
        const lado = i % 2 === 0 ? -1 : 1;
        const baseX = W/2 + lado * (180 + (i%6)*60);
        const baseY = H*0.55 + Math.floor(i/2)*40;
        const mueve = lado * (fase < 1 ? 0 : interpolate(fase, [1, 2], [0, 200], clamp));
        const x = baseX + mueve + Math.sin(s*0.6 + i) * 8;
        const y = baseY + Math.cos(s*0.5 + i) * 5;
        const escala = 0.6 + (i%3)*0.15;
        return (
          <div key={i} style={{position: 'absolute', left: x, top: y, transform: `scale(${escala})`, opacity: 0.7}}>
            <svg width={80} height={140} viewBox="0 0 80 140">
              <path d="M 20 130 L 25 50 Q 40 30 55 50 L 60 130 Z" fill="#3a3040" />
              <circle cx={40} cy={35} r={12} fill="#4a4050" />
            </svg>
          </div>
        );
      })}
    </AbsoluteFill>
  );
};

// Partículas de luz/curación
const ParticulasCuracion: React.FC<{s: number; activa: number; x: number; y: number}> = ({s, activa, x, y}) => {
  if (activa <= 0) return null;
  return (
    <AbsoluteFill style={{pointerEvents: 'none'}}>
      {Array.from({length: 30}).map((_, i) => {
        const ang = (i / 30) * Math.PI * 2;
        const radio = 30 + activa * 150 + Math.sin(s*2 + i) * 20;
        const px = x + Math.cos(ang) * radio;
        const py = y + Math.sin(ang) * radio * 0.6;
        const r = 3 + (i%4)*2;
        return <div key={i} style={{position: 'absolute', left: px, top: py, width: r, height: r, borderRadius: r, background: '#fff8d0', opacity: activa * (0.5 + 0.5*Math.sin(s*3+i)), boxShadow: '0 0 10px #ffe880', filter: 'blur(1px)'}} />;
      })}
    </AbsoluteFill>
  );
};

// Ánima de paz (ángel sutil, solo luz y alas)
const AngelPaz: React.FC<{s: number; intensidad: number; x: number; y: number}> = ({s, intensidad, x, y}) => {
  if (intensidad <= 0) return null;
  const aleteo = Math.sin(s * 2.5) * 15;
  return (
    <div style={{position: 'absolute', left: x - 80, top: y - 120, opacity: intensidad, pointerEvents: 'none', transform: `scale(${0.8 + 0.2*intensidad})`}}>
      <svg width={160} height={200} viewBox="0 0 160 200">
        {/* Alas */}
        <path d={`M 80 60 Q ${40 + aleteo} 20 20 80 Q 50 100 80 120 Q 110 100 ${140 - aleteo} 80 Q ${120 - aleteo} 20 80 60`} fill="rgba(255,255,255,0.15)" stroke="rgba(255,240,200,0.5)" strokeWidth={1} />
        <path d={`M 80 70 Q ${50 + aleteo*0.5} 40 40 85 Q 60 95 80 110 Q 100 95 ${120 - aleteo*0.5} 85 Q ${110 - aleteo*0.5} 40 80 70`} fill="rgba(255,255,255,0.1)" />
        {/* Luz central */}
        <circle cx={80} cy={90} r={30} fill="rgba(255,245,200,0.3)" filter="blur(15px)" />
        <circle cx={80} cy={90} r={15} fill="rgba(255,255,255,0.4)" filter="blur(8px)" />
      </svg>
    </div>
  );
};

// Viñeta y borde de luz
const Vineta: React.FC<{calida: number}> = ({calida}) => (
  <AbsoluteFill style={{pointerEvents: 'none', background: `radial-gradient(ellipse at 50% 55%, transparent 40%, rgba(10,8,20,${0.4 + calida*0.2}) 100%)`}} />
);

const BordeLuz: React.FC<{intensidad: number}> = ({intensidad}) => (
  <AbsoluteFill style={{pointerEvents: 'none', boxShadow: `inset 0 0 ${200*intensidad}px ${100*intensidad}px rgba(255,230,150,${0.15*intensidad})`}} />
);

export const Escena: React.FC = () => {
  const {s} = useS();

  // Progreso global para transiciones de cielo/luz
  const progresoGlobal = s / Math.max(DUR, 1);

  // Fases de la historia (0-4)
  const fase1 = interpolate(s, [CLAMAS - 1, GRITA2 + 0.5], [0, 1], clamp); // Inicio + grito
  const fase2 = interpolate(s, [DETIENE1 - 0.5, VA + 0.5], [0, 1], clamp); // Jesús llama
  const fase3 = interpolate(s, [PREGUNTA1 - 0.5, SIGUE + 0.5], [0, 1], clamp); // Sanación
  const fase4 = interpolate(s, [INVISIBLE - 0.5, AMEN + 1], [0, 1], clamp); // Aplicación personal

  // Posiciones de Bartimeo
  const bartX = interpolate(fase2, [0, 1], [W/2, W/2], clamp);
  const bartY = interpolate(fase2, [0, 1], [H*0.72, H*0.65], clamp);
  const bartEscala = interpolate(fase2, [0, 0.3, 1], [0.9, 0.85, 1.1], clamp);
  const bartFase = fase1 * 1 + fase2 * 1.5 + fase3 * 1.5;

  // Jesús aparece en fase2
  const jesusPresente = interpolate(fase2, [0.3, 0.8], [0, 1], clamp);
  const jesusX = W/2;
  const jesusY = H*0.45;

  // Luz divina crece en fase3
  const luzDivina = interpolate(fase3, [0.2, 0.8], [0, 1], clamp);

  // Partículas de curación en "vea" y "salvó"
  const particulasActiva = Math.max(
    interpolate(s, [VEA - 0.2, VEA + 2], [0, 1], clamp),
    interpolate(s, [SALVO - 0.2, SALVO + 2], [0, 1], clamp)
  );

  // Ángel de paz en fase4
  const angelIntensidad = interpolate(fase4, [0.2, 0.9], [0, 1], clamp);

  // Calidez global (oro) aumenta hacia el final
  const calidezGlobal = interpolate(s, [GRITA2, AMEN], [0, 1], clamp);

  // Zoom lento de cámara
  const zoom = 1.02 + 0.03 * Math.sin(s * 0.15);
  const derivaCam = Math.sin(s * 0.08) * 10;

  return (
    <AbsoluteFill style={{overflow: 'hidden', backgroundColor: '#1a1520'}}>
      <AbsoluteFill style={{transform: `scale(${zoom}) translateX(${derivaCam}px)`, transformOrigin: '50% 50%'}}>
        <Cielo progreso={progresoGlobal} />
        <LuzDivina intensidad={luzDivina} s={s} />
        <Rayos fuerza={luzDivina + calidezGlobal * 0.3} s={s} />
        <Camino progreso={progresoGlobal} s={s} />
        <Multitud s={s} fase={fase1} />
        <Bartimeo s={s} fase={bartFase} x={bartX} y={bartY} escala={bartEscala} />
        <Jesus s={s} presente={jesusPresente} x={jesusX} y={jesusY} escala={1.2} />
        <ParticulasCuracion s={s} activa={particulasActiva} x={bartX} y={bartY - 50} />
        <AngelPaz s={s} intensidad={angelIntensidad} x={W/2} y={H*0.35} />
        <Polvo s={s} calido={calidezGlobal} />
      </AbsoluteFill>
      <Vineta calida={calidezGlobal} />
      <BordeLuz intensidad={calidezGlobal} />
    </AbsoluteFill>
  );
};
